// v2.0: migration additive only. Legacy schema/version=1 remains export/import compatible.
const FORECAST_DEFAULTS={schema:2,reserve:300,horizon:90,salaryDay:27,expenseDay:25,allocationDay:28,salaryEnabled:false,expensesEnabled:false,allocationsEnabled:false,deadlineEnabled:false,bufferExtra:0};
function ensureForecast(){if(!state.forecast||typeof state.forecast!=='object')state.forecast={...FORECAST_DEFAULTS};else for(const [k,v] of Object.entries(FORECAST_DEFAULTS))if(state.forecast[k]===undefined)state.forecast[k]=v;}
function localISO(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function datePlus(date,n){const [y,m,d]=date.split('-').map(Number);return localISO(new Date(y,m-1,d+n))}
function monthDay(period,day){const [y,m]=period.split('-').map(Number);return `${period}-${String(Math.min(day,new Date(y,m,0).getDate())).padStart(2,'0')}`}
function isMatchedMonthly(period,type,category,from,to){return state.transactions.some(t=>t.date?.startsWith(period)&&t.type===type&&(category===null||t.category===category)&&(from===null||t.from===from)&&(to===null||t.to===to))}
function forecastEvents(start,end){
 ensureForecast();const f=state.forecast,events=[];const add=(e)=>{if(e.date>start&&e.date<=end)events.push(e)};
 const first=start.slice(0,7),last=end.slice(0,7);let [y,m]=first.split('-').map(Number);
 while(`${y}-${String(m).padStart(2,'0')}`<=last){
  const period=`${y}-${String(m).padStart(2,'0')}`;
  if(f.salaryEnabled&&!isMatchedMonthly(period,'income','Stipendio',null,'free'))add({id:`salary-${period}`,date:monthDay(period,f.salaryDay),kind:'income',label:'Stipendio previsto',to:'free',amount:Number(state.incomeMonthly)||0});
  if(f.expensesEnabled)for(const [category,monthly] of state.budget){
   // Residual budget for current month; full budget in future months. Not an extra expense on top of transactions.
   const paid=sum(state.transactions.filter(t=>t.date?.startsWith(period)&&t.type==='expense'&&t.category===category&&t.from==='free').map(t=>Number(t.amount)||0));
   const remaining=Math.max(0,Number(monthly)-paid);
   if(remaining>0)add({id:`expense-${period}-${category}`,date:monthDay(period,f.expenseDay),kind:'expense',label:`Budget residuo: ${category}`,from:'free',amount:remaining});
  }
  if(f.allocationsEnabled)for(const a of state.accounts){if(a.id==='free')continue;const amount=Number(a.goal?.monthly)||0;
   if(amount<=0)continue;
   const already=sum(state.transactions.filter(t=>t.type==='transfer'&&t.date?.startsWith(period)&&t.from==='free'&&t.to===a.id).map(t=>Number(t.amount)||0));
   const remaining=Math.max(0,amount-already);
   if(remaining>0)add({id:`allocation-${period}-${a.id}`,date:monthDay(period,f.allocationDay),kind:'transfer',label:`Accantonamento ${a.name}`,from:'free',to:a.id,amount:remaining});
  }
  m++;if(m>12){m=1;y++}
 }
 if(f.deadlineEnabled)for(const d of state.deadlines){if(d.done||!d.date||!Number.isFinite(Number(d.amount))||Number(d.amount)<=0)continue;
  // If a corresponding expense was recorded on the same fund in the deadline month, do not project again.
  if(state.transactions.some(t=>t.type==='expense'&&t.from===d.account&&t.date?.startsWith(d.date.slice(0,7))&&Math.abs(Number(t.amount)-Number(d.amount))<0.01))continue;
  add({id:`deadline-${d.id}`,date:d.date,kind:'expense',label:d.name,from:d.account,amount:Number(d.amount),deadline:true});
 }
 return events.sort((a,b)=>a.date.localeCompare(b.date)||a.id.localeCompare(b.id));
}
function forecastCalculate(){
 ensureForecast();const start=todayLocal(),end=datePlus(start,Math.max(1,Math.min(365,Number(state.forecast.horizon)||90)));
 const accounts=Object.fromEntries(state.accounts.map(a=>[a.id,bal(a.id)]));
 const events=forecastEvents(start,end),days=[],warnings=[];let minFree=accounts.free, minDate=start;
 const grouped=new Map();for(const e of events){if(!grouped.has(e.date))grouped.set(e.date,[]);grouped.get(e.date).push(e)}
 for(let d=datePlus(start,1);d<=end;d=datePlus(d,1)){
  for(const e of grouped.get(d)||[]){if(e.from)accounts[e.from]=(accounts[e.from]||0)-e.amount;if(e.to)accounts[e.to]=(accounts[e.to]||0)+e.amount;
   if(e.deadline&&accounts[e.from]<0)warnings.push(`${e.label}: fondo ${e.from} insufficiente il ${fmtDate(d)} (${euro(accounts[e.from])})`);
  }
  if(accounts.free<minFree){minFree=accounts.free;minDate=d}
  days.push({date:d,free:accounts.free});
 }
 const reserve=Number(state.forecast.reserve)||0,raw=Math.min(bal('free'),minFree)-reserve;
 return {start,end,events,days,minFree,minDate,reserve,available:Math.max(0,raw),shortfall:Math.max(0,-raw),warnings};
}
function forecastCard(){const p=forecastCalculate(),f=state.forecast;
 const W=720,H=260,L=68,R=20,T=22,B=42,values=[bal('free'),...p.days.map(x=>x.free)],min=Math.min(0,...values),max=Math.max(1,...values),x=i=>L+i*(W-L-R)/Math.max(1,p.days.length),y=v=>T+(H-T-B)*(1-(v-min)/(max-min||1));
 const line=[`${x(0)},${y(values[0])}`,...p.days.map((d,i)=>`${x(i+1)},${y(d.free)}`)].join(' ');
 const zero=y(0),res=y(p.reserve),today=bal('free');
 const ticks=[0,.25,.5,.75,1].map(t=>{const val=min+(max-min)*t;return `<line x1="${L}" y1="${y(val)}" x2="${W-R}" y2="${y(val)}" stroke="currentColor" opacity=".12"/><text x="${L-8}" y="${y(val)+4}" text-anchor="end" fill="currentColor" font-size="11">${Math.round(val)}</text>`}).join('');
 return card('Previsione liquidità · 90 giorni',`<div class="grid">${card('Disponibilità prudenziale',`<div class="metric ${p.shortfall?'bad':'good'}">${euro(p.available)}</div><small>Riserva protetta: ${euro(p.reserve)}</small>`)}${card('Minimo previsto',`<div class="metric ${p.minFree<p.reserve?'bad':''}">${euro(p.minFree)}</div><small>${fmtDate(p.minDate)}</small>`)}</div><div class="timeline-scroll"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Previsione della liquidità libera per i prossimi 90 giorni"><line x1="${L}" x2="${W-R}" y1="${res}" y2="${res}" stroke="#e59b36" stroke-dasharray="7 5" stroke-width="2"/>${ticks}<polyline points="${line}" fill="none" stroke="#0d9488" stroke-width="3"/><text x="${L}" y="${H-10}" fill="currentColor" font-size="12">${fmtDate(p.start)}</text><text x="${W-R}" y="${H-10}" text-anchor="end" fill="currentColor" font-size="12">${fmtDate(p.end)}</text></svg></div>${p.shortfall?`<div class="notice bad">Margine da coprire per mantenere la riserva: <strong>${euro(p.shortfall)}</strong>. Non effettuare spese discrezionali sulla base di questa previsione.</div>`:`<div class="notice">Disponibilità stimata spendibile oggi: <strong>${euro(p.available)}</strong>, mantenendo la riserva di ${euro(p.reserve)}.</div>`}${p.warnings.length?`<div class="notice">${p.warnings.map(esc).join('<br>')}</div>`:''}<p class="muted">Stima basata solo sulle opzioni abilitate: date ipotetiche da verificare. Le previsioni automatiche sono inizialmente disattivate. Le previsioni non modificano i saldi reali. Pagamenti dai fondi dedicati non scalano nuovamente la liquidità libera.</p><button type="button" onclick="setTab('forecast')">⚙ Configura previsioni e vedi eventi</button>`);
}
function forecastPage(){ensureForecast();const f=state.forecast,p=forecastCalculate();layout(card('Parametri previsionali',`<p class="muted">Le date sono ipotesi modificabili. Le opzioni sono inizialmente disattivate: attivale solo dopo aver verificato le date. Nessuna previsione genera un movimento reale.</p><form id="forecastForm"><div class="formgrid"><div><label>Riserva minima (€)</label><input name="reserve" type="number" min="0" step="1" value="${f.reserve}" required></div><div><label>Giorno stipendio (1–28)</label><input name="salaryDay" type="number" min="1" max="28" value="${f.salaryDay}" required></div><div><label>Giorno budget spese (1–28)</label><input name="expenseDay" type="number" min="1" max="28" value="${f.expenseDay}" required></div><div><label>Giorno accantonamenti (1–28)</label><input name="allocationDay" type="number" min="1" max="28" value="${f.allocationDay}" required></div></div><p><label><input type="checkbox" name="salaryEnabled" ${f.salaryEnabled?'checked':''}> Prevedi stipendio mensile</label></p><p><label><input type="checkbox" name="expensesEnabled" ${f.expensesEnabled?'checked':''}> Prevedi spese del budget</label></p><p><label><input type="checkbox" name="allocationsEnabled" ${f.allocationsEnabled?'checked':''}> Prevedi accantonamenti verso fondi</label></p><p><label><input type="checkbox" name="deadlineEnabled" ${f.deadlineEnabled?'checked':''}> Prevedi pagamenti delle scadenze dai fondi</label></p><button class="primary">Salva parametri</button></form>`)+card('Eventi previsti nei prossimi 90 giorni',`<p class="muted">Nessun evento qui sotto è già contabilizzato.</p>${p.events.length?p.events.map(e=>`<div class="entry"><div class="row"><span>${fmtDate(e.date)} · ${esc(e.label)}</span><strong>${e.from==='free'?'-':e.to==='free'?'+':'↔'} ${euro(e.amount)}</strong></div><small>${esc(e.kind)} · ${esc(e.from||'esterno')} → ${esc(e.to||'esterno')}</small></div>`).join(''):'<p>Nessun evento previsto.</p>'}`));$('forecastForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);for(const name of ['reserve','salaryDay','expenseDay','allocationDay'])f[name]=Number(fd.get(name));for(const name of ['salaryEnabled','expensesEnabled','allocationsEnabled','deadlineEnabled'])f[name]=fd.has(name);await save();forecastPage()}}

function ensureInsights(){if(!state.insights||typeof state.insights!=='object')state.insights={inflation:null,inflationMonth:'',inflationStatus:'',inflationSource:'',inflationChecked:'',depositRate:2,navLabels:true,savingTarget:20};const v=state.insights;if(!Number.isFinite(Number(v.depositRate)))v.depositRate=2;if(typeof v.navLabels!=='boolean')v.navLabels=true;if(!Number.isFinite(Number(v.savingTarget)))v.savingTarget=20}
function applyNavLabels(){ensureInsights();document.body.classList.toggle('nav-icons-only',!state.insights.navLabels);const toggle=document.getElementById('navLabelToggle');if(toggle){toggle.setAttribute('aria-pressed',String(state.insights.navLabels));toggle.title=state.insights.navLabels?'Nascondi testi':'Mostra testi'}}
async function toggleNavLabels(){ensureInsights();state.insights.navLabels=!state.insights.navLabels;await save();applyNavLabels()}
window.toggleNavLabels=toggleNavLabels;
function savingMetrics(){const entries=state.transactions.filter(t=>t.date&&t.date.startsWith(month()));const income=sum(entries.filter(t=>t.type==='income').map(t=>Number(t.amount)||0));const expenses=sum(entries.filter(t=>t.type==='expense').map(t=>Number(t.amount)||0));const planned=sum(state.allocations.map(x=>Number(x[1])||0));return {income,expenses,planned,actual:income>0?(income-expenses)/income*100:null,plannedRate:state.incomeMonthly>0?planned/state.incomeMonthly*100:null}}
function financeInsightsCard(){ensureInsights();const v=state.insights,m=savingMetrics(),inf=Number(v.inflation),hasInfl=v.inflation!==null&&v.inflation!==''&&Number.isFinite(inf),nom=Number(v.depositRate)*.74-.2,real=hasInfl?((1+nom/100)/(1+inf/100)-1)*100:null;return card('Risparmio · Inflazione · Findomestic',`<div class="insight-grid"><div><small>Risparmio programmato / stipendio</small><div class="metric">${m.plannedRate===null?'—':m.plannedRate.toFixed(1)+'%'}</div><div class="muted">${euro(m.planned)} al mese · obiettivo ${v.savingTarget}%</div></div><div><small>Risparmio effettivo del mese</small><div class="metric">${m.actual===null?'—':m.actual.toFixed(1)+'%'}</div><div class="muted">${m.actual===null?'Mancano entrate registrate':'Entrate meno spese registrate; mese parziale se incompleto'}</div></div><div><small>Inflazione ISTAT NIC annua</small><div class="metric">${hasInfl?inf.toFixed(1)+'%':'—'}</div><div class="muted">${hasInfl?esc(v.inflationMonth)+' · '+esc(v.inflationStatus):'Dato ufficiale non ancora verificato'}</div></div><div><small>Rendimento reale Findomestic</small><div class="metric ${real!==null&&real<0?'bad':'good'}">${real===null?'—':real.toFixed(2)+'%'}</div><div class="muted">${nom.toFixed(2)}% nominale netto stimato · tasso lordo ${Number(v.depositRate).toFixed(2)}%</div></div></div><p class="muted">Il rendimento reale è una simulazione annua a saldo costante, bollo stimato 0,20% e ritenuta 26%. L'inflazione annua osservata non è una previsione futura.</p><div class="actions"><button type="button" onclick="checkIstat()">Verifica ISTAT</button><button type="button" onclick="setTab('settings')">Configura indicatori</button></div>${v.inflationChecked?`<p class="muted">Ultimo tentativo: ${esc(v.inflationChecked)}. Fonte: ${v.inflationSource?`<a href="${esc(v.inflationSource)}" target="_blank" rel="noopener noreferrer">ISTAT</a>`:'non verificata'}</p>`:''}`)}
// Il browser può bloccare le richieste a ISTAT (CORS). Non sostituire mai un valore validato con un numero non verificato.
async function checkIstat(){ensureInsights();const v=state.insights;v.inflationChecked=new Date().toLocaleString('it-IT');await save();const url='https://www.istat.it/it/archivio/prezzi+al+consumo';window.open(url,'_blank','noopener,noreferrer');alert('Consulta il comunicato ISTAT più recente sui prezzi al consumo (NIC generale, variazione annua). Inserisci valore, mese e stato nella scheda Dati. La lettura automatica non è disponibile in questa versione senza un endpoint ISTAT compatibile con il browser.');if(tab==='dashboard')dashboard()}
window.checkIstat=checkIstat;
// v2.4.4: conservative deadline coverage; informational only, no automatic postings.
function deadlineCoverage(){
 const now=todayLocal(), items=state.deadlines.filter(d=>!d.done&&d.date>=now&&Number(d.amount)>0).sort((a,b)=>a.date.localeCompare(b.date));
 const reserved={};const rows=items.map(d=>{
  const amount=Number(d.amount),id=d.account||'free';
  // One fund may cover multiple deadlines: do not reuse the same balance.
  const available=Math.max(0,(id==='free'?0:bal(id))-(reserved[id]||0));
  const covered=Math.min(amount,available);reserved[id]=(reserved[id]||0)+covered;
  return {...d,amount,covered,missing:Math.max(0,amount-covered)};
 });
 const nextPay=(()=>{const [y,m,day]=now.split('-').map(Number);return localISO(new Date(y,m-1+(day>=27?1:0),27))})();
 const near=rows.filter(d=>d.date<=nextPay),horizon=datePlus(now,90),quarter=rows.filter(d=>d.date<=horizon);
 const reserve=Math.max(0,Number(state.forecast?.reserve??300));
 const liquid=freeTotal(),base=Math.max(0,liquid-reserve);
 const immediateUncovered=sum(near.map(d=>d.missing));
 return {rows,near,quarter,nextPay,reserve,liquid,base,immediateUncovered,available:Math.max(0,base-immediateUncovered),quarterMissing:sum(quarter.map(d=>d.missing))};
}
function deadlineCoverageCard(){const c=deadlineCoverage();return card('Disponibilità prudenziale · scadenze',`<div class="grid">${card('Liquidità operativa',`<div class="metric">${euro(c.liquid)}</div><small>Conto e contanti; non include fondi protetti</small>`)}${card('Oltre la riserva',`<div class="metric">${euro(c.base)}</div><small>Riserva minima ${euro(c.reserve)}</small>`)}${card('Scadenze scoperte prima del ${fmtDate(c.nextPay)}',`<div class="metric ${c.immediateUncovered?'bad':''}">${euro(c.immediateUncovered)}</div><small>Solo importi non coperti da fondi dedicati</small>`)}${card('Margine dopo scadenze note',`<div class="metric">${euro(c.available)}</div><small>Non include spese ordinarie non ancora registrate</small>`)}</div><p class="muted">Scadenze entro 90 giorni: importo non coperto ${euro(c.quarterMissing)}. I fondi già separati non vengono sottratti nuovamente. Le scadenze sono informative: nessun saldo viene modificato.</p>${c.rows.slice(0,5).map(d=>`<div class="row"><span>${esc(d.name)} · ${fmtDate(d.date)}</span><strong>${euro(d.covered)} coperti / ${euro(d.missing)} mancanti</strong></div>`).join('')||'<p class="muted">Nessuna scadenza futura registrata.</p>'}<div class="notice">Stima parziale: non sottrae bollette, alimentari o altre uscite future prive di scadenza. Le date indicate come provvisorie devono essere confermate. Non usare il margine come autorizzazione di spesa.</div>`)}
function dashboard(){ensureV24();const free=freeTotal(),family=familyAssets(),children=childrenAssets(),target=state.accounts.find(a=>a.id==='emergency')?.goal?.target||8000,p=forecastCalculate(),period=month(),d=reportData(period),r=financialRange(period);layout(`<div class="grid">${card('Liquidità libera',`<div class="metric">${euro(free)}</div><small>Conto ${euro(bal('free'))}${cashAccount()?' · Contanti '+euro(bal('cash')):''} · Riserva minima ${euro(p.reserve)}</small>`)}${card('Patrimonio famiglia',`<div class="metric">${euro(family)}</div><small>Conti e fondi familiari; esclude i risparmi dei figli</small>`)}${card('Patrimonio figli',`<div class="metric">${euro(children.total)}</div><small>Leonardo (Scalable) ${euro(children.leo)} · Bianca (libretto) ${euro(children.bianca)}</small>`)}${card('Fondo emergenza',`<div class="metric">${euro(bal('emergency'))}</div><div class="bar"><div class="fill" style="width:${Math.max(0,Math.min(100,bal('emergency')/target*100))}%"></div></div><small>Obiettivo ${euro(target)}</small>`)}</div>${p.shortfall?`<div class="notice bad">Attenzione: mancano ${euro(p.shortfall)} per rispettare la riserva prevista.</div>`:''}${deadlineCoverageCard()}${temporalChart(todayLocal().slice(0,7),window.dashboardTimelineMode||'daily')}${card('Bilancio del mese finanziario',`<p class="muted">${fmtDate(r.start)} – ${fmtDate(r.end)}</p><div class="row"><span>Entrate registrate</span><strong>${euro(d.income)}</strong></div><div class="row"><span>Spese registrate</span><strong>${euro(d.expense)}</strong></div><div class="row"><span>Saldo netto registrato</span><strong>${euro(d.income-d.expense)}</strong></div><button type="button" onclick="setTab('budgetPage')">Apri Bilancio & Budget</button>`)}<details class="card"><summary><strong>Spese per categoria</strong></summary>${expenseDonut(d.expenseCats)}</details>${card('Prossime scadenze',state.deadlines.filter(x=>!x.done).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,3).map(x=>`<div class="row"><span>${esc(x.name)} · ${fmtDate(x.date)}</span><strong>${euro(x.amount)}</strong></div>`).join('')||'Nessuna scadenza aperta')}<details class="card"><summary><strong>Budget e indicatori avanzati</strong></summary><p>Margine medio annuo stimato: ${euro(budgetAnalysis().monthly)}/mese. Non è disponibilità immediata; disponibilità prudenziale oggi: ${euro(p.available)}.</p>${forecastCard()}${financeInsightsCard()}</details>`);const selector=$('timelineMode');if(selector)selector.onchange=e=>{window.dashboardTimelineMode=e.target.value;dashboard()}}

const EXTRA_INCOME=['Stipendio','Tredicesima','Quattordicesima','Rimborso','Altro'];
const EXTRA_EXPENSE=['Altro','Auto - assicurazione','Auto - bollo','Auto - manutenzione'];
function ensureCategories(){if(!state.categories||typeof state.categories!=='object')state.categories={};for(const t of ['expense','income'])if(!Array.isArray(state.categories[t]))state.categories[t]=[]}
function categories(t){ensureCategories();return [...new Set((t==='income'?EXTRA_INCOME:state.budget.map(x=>x[0]).concat(EXTRA_EXPENSE)).concat(state.categories[t]))]}
function catOptions(t,selected){return categories(t).map(x=>`<option value="${esc(x)}" ${x===selected?'selected':''}>${esc(x)}</option>`).join('')}
function catPanel(){ensureCategories();return card('Gestione categorie',`<p class="muted">Crea categorie per spese ed entrate. Le nuove categorie di spesa hanno budget iniziale 0 €. La rinomina aggiorna movimenti e preferiti. Non puoi eliminare categorie ancora utilizzate.</p><form id="catForm" class="formgrid"><div><label>Tipo</label><select name="type"><option value="expense">Spesa</option><option value="income">Entrata</option></select></div><div><label>Nome</label><input name="name" maxlength="50" required placeholder="Es. Animali domestici"></div><div class="full"><button class="primary">+ Crea categoria</button></div></form>${['expense','income'].map(t=>`<h3>${t==='expense'?'Spese':'Entrate'} personalizzate</h3>${state.categories[t].map(n=>`<div class="entry row"><strong>${esc(n)}</strong><span class="actions"><button data-cat-edit="${esc(n)}" data-type="${t}">Rinomina</button><button class="danger" data-cat-del="${esc(n)}" data-type="${t}">Elimina</button></span></div>`).join('')||'<p class="muted">Nessuna categoria personalizzata.</p>'}`).join('')}`)}
function initCats(){
 $('catForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),t=f.get('type'),n=String(f.get('name')||'').trim().replace(/\s+/g,' ');if(!n||n.length>50)return alert('Nome non valido');if(categories(t).some(x=>x.toLowerCase()===n.toLowerCase()))return alert('Categoria già esistente');state.categories[t].push(n);if(t==='expense')state.budget.push([n,0]);await save();settings()};
 document.querySelectorAll('[data-cat-edit]').forEach(b=>b.onclick=async()=>{let old=b.dataset.catEdit,t=b.dataset.type,n=prompt('Nuovo nome:',old)?.trim().replace(/\s+/g,' ');if(!n||n===old)return;if(n.length>50||categories(t).some(x=>x.toLowerCase()===n.toLowerCase()))return alert('Nome non valido o duplicato');state.categories[t]=state.categories[t].map(x=>x===old?n:x);if(t==='expense')state.budget=state.budget.map(x=>x[0]===old?[n,x[1]]:x);state.transactions.forEach(x=>{if(x.type===t&&x.category===old)x.category=n});if(Array.isArray(state.quickFavorites))state.quickFavorites.forEach(x=>{if(x.type===t&&x.category===old)x.category=n});await save();settings()});
 document.querySelectorAll('[data-cat-del]').forEach(b=>b.onclick=async()=>{let n=b.dataset.catDel,t=b.dataset.type;if(state.transactions.some(x=>x.type===t&&x.category===n)||quickFavorites().some(x=>x.type===t&&x.category===n))return alert('Categoria usata da movimenti o preferiti: non eliminabile');if(!confirm('Eliminare '+n+'?'))return;state.categories[t]=state.categories[t].filter(x=>x!==n);if(t==='expense')state.budget=state.budget.filter(x=>x[0]!==n);await save();settings()});
}

const QUICK_CATS=[['Alimentari','🛒'],['Carburante','⛽'],['Pranzi lavoro','🍽️'],['Farmacia','💊'],['Pannolini','👶'],['Altro','⋯']];
const QUICK_DEFAULTS=[{name:'Pranzo lavoro',type:'expense',amount:8,category:'Pranzi lavoro',from:'free'},{name:'Diesel',type:'expense',amount:50,category:'Carburante',from:'free'},{name:'Supermercato',type:'expense',amount:null,category:'Alimentari',from:'free'},{name:'Fondo emergenza',type:'transfer',amount:200,category:'Accantonamento',from:'free',to:'emergency'}];
function todayLocal(){let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function quickFavorites(){return Array.isArray(state.quickFavorites)?state.quickFavorites:QUICK_DEFAULTS}
function quickPanel(){return card('⚡ Movimento rapido',`<form id="quickForm" class="quickform"><div class="quicktypes"><button type="button" class="selected" data-qtype="expense">Spesa</button><button type="button" data-qtype="income">Entrata</button><button type="button" data-qtype="transfer">Trasferimento</button></div><div class="quickamount"><label for="qamount">IMPORTO (€)</label><input id="qamount" name="amount" type="number" min="0.01" step="0.01" inputmode="decimal" placeholder="0,00" required></div><div id="quickCategories"></div><div class="formgrid"><div><label>Data</label><input type="date" name="date" required value="${todayLocal()}"></div><div id="quickFrom"><label>Da conto</label><select name="from">${accountOptions()}</select></div><div id="quickTo" hidden><label>A conto</label><select name="to">${accountOptions()}</select></div></div><div><label>Nota (facoltativa)</label><input name="note" maxlength="180" placeholder="Descrizione"></div><div class="actions"><button class="primary" type="submit" name="saveMode" value="done">Salva movimento</button><button type="submit" name="saveMode" value="again">Salva e nuovo</button></div></form><div id="quickFeedback" class="muted" role="status" aria-live="polite"></div><div class="quickfavhead"><strong>⭐ Preferiti</strong><button id="saveFavorite" type="button">+ Salva preferito</button></div><div class="quickfavorites" id="quickFavorites"></div><div class="notice">I preferiti compilano i campi ma non registrano nulla. I trasferimenti non sono spese. Per opzioni avanzate usa il modulo sottostante.</div>`)}
let quickType='expense',quickCategory='Alimentari',quickSubmitMode='done';
function initQuick(){let f=$('quickForm');if(!f)return;const select=(name)=>f.elements.namedItem(name);const renderCats=()=>{let c=$('quickCategories');if(quickType==='expense'){c.innerHTML=`<label>Categoria</label><div class="quickchips">${QUICK_CATS.map(([name,ico])=>`<button type="button" data-qcat="${esc(name)}" class="${quickCategory===name?'selected':''}"><span>${ico}</span>${esc(name)}</button>`).join('')}</div><label for="qcatother">Oppure seleziona categoria</label><select id="qcatother">${catOptions('expense',quickCategory)}</select>`;c.querySelectorAll('[data-qcat]').forEach(b=>b.onclick=()=>{quickCategory=b.dataset.qcat;renderCats()});$('qcatother').onchange=e=>{quickCategory=e.target.value;renderCats()}}else if(quickType==='income'){c.innerHTML=`<label>Categoria</label><select id="qcatother">${catOptions('income',quickCategory)}</select>`;$('qcatother').onchange=e=>quickCategory=e.target.value}else{c.innerHTML='<p class="muted">Sposta denaro tra due conti/fondi senza creare una spesa.</p>';quickCategory='Accantonamento'}$('quickFrom').hidden=quickType==='income';$('quickTo').hidden=quickType==='expense';f.querySelectorAll('[data-qtype]').forEach(b=>b.classList.toggle('selected',b.dataset.qtype===quickType))};
function setType(type){quickType=type;quickCategory=type==='expense'?'Alimentari':type==='income'?'Stipendio':'Accantonamento';renderCats()}
f.querySelectorAll('[data-qtype]').forEach(b=>b.onclick=()=>setType(b.dataset.qtype));
function renderFavorites(){$('quickFavorites').innerHTML=quickFavorites().map((x,i)=>`<div class="quickfavorite"><button type="button" data-fav="${i}">${esc(x.name)}${x.amount!=null?' · '+euro(x.amount):''}</button><button type="button" data-unfav="${i}" aria-label="Elimina preferito ${esc(x.name)}" title="Elimina preferito">×</button></div>`).join('');document.querySelectorAll('[data-fav]').forEach(b=>b.onclick=()=>{let x=quickFavorites()[Number(b.dataset.fav)];setType(x.type);quickCategory=x.category||quickCategory;renderCats();select('amount').value=x.amount??'';select('from').value=x.from||'free';select('to').value=x.to||'free';select('note').value='';$('qamount').focus()});document.querySelectorAll('[data-unfav]').forEach(b=>b.onclick=async()=>{let i=Number(b.dataset.unfav);if(!confirm('Eliminare questo preferito?'))return;state.quickFavorites=quickFavorites().filter((_,j)=>j!==i);await save();renderFavorites()})}
$('saveFavorite').onclick=async()=>{let name=prompt('Nome del nuovo preferito:');if(!name||!name.trim())return;name=name.trim().slice(0,45);let amount=Number(select('amount').value);let fav={name,type:quickType,amount:amount>0?amount:null,category:quickCategory,from:select('from').value,to:select('to').value};state.quickFavorites=[...quickFavorites(),fav];await save();renderFavorites()};
f.querySelectorAll('button[type="submit"]').forEach(b=>b.onclick=()=>quickSubmitMode=b.value);
f.onsubmit=async e=>{e.preventDefault();let amount=Number(select('amount').value),from=select('from').value,to=select('to').value;if(!Number.isFinite(amount)||amount<=0)return alert('Importo non valido');if(quickType==='transfer'&&(!from||!to||from===to))return alert('Origine e destinazione devono essere diverse');if(!confirm(`Confermi ${quickType==='expense'?'la spesa':quickType==='income'?'l’entrata':'il trasferimento'} di ${euro(amount)}?`))return;let t={id:uid(),date:select('date').value,type:quickType,amount,category:quickCategory,from:quickType==='income'?'':from,to:quickType==='expense'?'':to,note:select('note').value};if(!validateCashChange(t))return;state.transactions.push(t);try{await save()}catch(err){state.transactions.pop();return alert('Salvataggio non riuscito: '+err.message)}if(quickSubmitMode==='again'){select('amount').value='';select('note').value='';$('quickFeedback').textContent='Movimento salvato. Puoi inserirne un altro.';listTx();$('qamount').focus()}else movements()};setType('expense');renderFavorites()}
function movements(){layout(quickPanel()+card('Movimento dettagliato',`<form id="txform" class="formgrid"><div><label>Data</label><input name="date" type="date" required value="${new Date().toLocaleDateString('en-CA')}"></div><div><label>Tipo</label><select name="type" id="txtype"><option value="expense">Spesa</option><option value="income">Entrata</option><option value="transfer">Trasferimento tra fondi</option></select></div><div><label>Importo (€)</label><input name="amount" type="number" min="0.01" step="0.01" required></div><div><label>Categoria</label><select name="category">${[...new Set(categories('expense').concat(categories('income')))].map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div><label>Da conto</label><select name="from"><option value="">—</option>${accountOptions()}</select></div><div><label>A conto</label><select name="to"><option value="">—</option>${accountOptions()}</select></div><div class="full"><label>Descrizione (facoltativa)</label><input name="note" maxlength="180" placeholder="Es. spesa supermercato"></div><div class="full"><button class="primary" type="submit">Salva movimento</button></div></form><div class="notice">Spesa: seleziona il conto di origine. Entrata: seleziona il conto di destinazione. Trasferimento: seleziona entrambi, diversi. Per pagare una fattura con denaro già accantonato, registra una spesa dal relativo fondo.</div>`)+card('Movimenti registrati',`<div class="actions"><label for="filterMonth">Mese</label><input style="max-width:190px" type="month" id="filterMonth" value="${window.selectedMonth||month()}"></div><div id="txlist"></div>`));initQuick();$('txform').onsubmit=addTx;$('filterMonth').onchange=e=>{window.selectedMonth=e.target.value;listTx()};listTx()}
function listTx(){let entries=state.transactions.filter(x=>periodMatch(x,window.selectedMonth||month())).sort((a,b)=>b.date.localeCompare(a.date));$('txlist').innerHTML=entries.map(t=>`<div class="entry"><div class="row"><strong>${esc(t.note||t.category)}</strong><strong class="${t.type==='expense'?'bad':t.type==='income'?'good':''}">${t.type==='expense'?'-':t.type==='income'?'+':'↔'} ${euro(t.amount)}</strong></div><small>${fmtDate(t.date)} · ${esc(t.category)} · ${t.type==='transfer'?'Trasferimento':t.type==='expense'?'Spesa':'Entrata'}</small><button class="danger" data-delete="${esc(t.id)}">Elimina</button></div>`).join('')||'<p class="muted">Nessun movimento nel mese.</p>';document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{await removeTx(b.dataset.delete,movements)})}
async function addTx(e){e.preventDefault();let f=new FormData(e.target),t={id:uid(),date:f.get('date'),type:f.get('type'),amount:Number(f.get('amount')),category:f.get('category'),from:f.get('from'),to:f.get('to'),note:f.get('note')};if(!Number.isFinite(t.amount)||t.amount<=0)return alert('Importo non valido');if(t.type==='expense'){if(!t.from)return alert('Seleziona il conto da cui paghi');t.to=''}if(t.type==='income'){if(!t.to)return alert('Seleziona il conto su cui ricevi');t.from=''}if(t.type==='transfer'){if(!t.from||!t.to||t.from===t.to)return alert('Seleziona due conti diversi')}if(!validateCashChange(t))return;state.transactions.push(t);await save();movements()}
function funds(){layout(card('Fondi e obiettivi',`<p class="muted">I saldi derivano dal saldo iniziale più i movimenti. Gli obiettivi e i versamenti programmati non modificano la liquidità.</p>${state.accounts.map(a=>{let current=bal(a.id),target=a.goal?.target,monthly=a.goal?.monthly||0,pct=target>0?Math.max(0,Math.min(100,current/target*100)):null,remaining=target>0?Math.max(0,target-current):null,months=remaining!==null&&monthly>0?Math.ceil(remaining/monthly):null;return `<div class="entry"><div class="row"><strong>${esc(a.name)}</strong><strong>${euro(current)}</strong></div>${target>0?`<div class="bar"><div class="fill" style="width:${pct}%"></div></div><small>Obiettivo ${euro(target)} · ${pct.toFixed(1)}% · Mancano ${euro(remaining)}${months!==null?' · Circa '+months+' mesi':''}</small>`:'<small>Obiettivo non impostato</small>'}<small>Versamento programmato ${euro(monthly)}/mese · Saldo iniziale ${euro(a.opening)}</small></div>`}).join('')}`)+card('Modifica fondo',`<form id="goalForm" class="formgrid"><div><label>Conto / fondo</label><select name="id" id="goalId">${state.accounts.map(a=>`<option value="${esc(a.id)}">${esc(a.name)}</option>`).join('')}</select></div><div><label>Saldo iniziale (€)</label><input type="number" name="opening" step="0.01" required></div><div><label>Obiettivo (€) — facoltativo</label><input type="number" name="target" min="0" step="0.01" placeholder="Non impostato"></div><div><label>Versamento previsto (€ / mese)</label><input type="number" name="monthly" min="0" step="0.01" required></div><div class="full"><button class="primary">Salva configurazione</button></div></form><div class="notice">Correggi il saldo iniziale solo per rettificare la situazione di partenza. Per versamenti successivi usa un trasferimento fra conti; non registrarlo come spesa.</div>`));let form=$('goalForm'),selector=$('goalId');function fill(){let a=state.accounts.find(x=>x.id===selector.value);form.elements.opening.value=a.opening;form.elements.target.value=a.goal?.target??'';form.elements.monthly.value=a.goal?.monthly??0}selector.onchange=fill;fill();form.onsubmit=async e=>{e.preventDefault();let f=new FormData(form),a=state.accounts.find(x=>x.id===f.get('id')),opening=Number(f.get('opening')),target=f.get('target')===''?null:Number(f.get('target')),monthly=Number(f.get('monthly'));if(!Number.isFinite(opening)||!Number.isFinite(monthly)||monthly<0||(target!==null&&(!Number.isFinite(target)||target<0)))return alert('Verifica gli importi');a.opening=opening;a.goal={target,monthly};await save();funds()}}
function deadlines(){layout(card('Nuova scadenza',`<form id="deadlineForm" class="formgrid"><div><label>Descrizione</label><input name="name" required></div><div><label>Data</label><input name="date" type="date" required></div><div><label>Importo (€)</label><input name="amount" type="number" min="0" step="0.01" required></div><div><label>Fondo associato</label><select name="account">${accountOptions()}</select></div><div class="full"><label>Note</label><input name="note"></div><div class="full"><button class="primary">Aggiungi scadenza</button></div></form>`)+card('Calendario scadenze',state.deadlines.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(d=>`<div class="entry"><div class="row"><strong>${esc(d.name)}</strong><strong>${euro(d.amount)}</strong></div><small>${fmtDate(d.date)} · ${d.done?'Completata':'Da pagare'} · ${esc(d.note||'')}</small><div class="actions"><button data-toggle="${esc(d.id)}">${d.done?'Riapri':'Segna completata'}</button><button class="danger" data-remove="${esc(d.id)}">Elimina</button></div></div>`).join('')||'Nessuna scadenza'));$('deadlineForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target);state.deadlines.push({id:uid(),name:f.get('name'),date:f.get('date'),amount:Number(f.get('amount')),account:f.get('account'),note:f.get('note'),done:false});await save();deadlines()};document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=async()=>{let d=state.deadlines.find(x=>x.id===b.dataset.toggle);d.done=!d.done;await save();deadlines()});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=async()=>{if(confirm('Eliminare la scadenza?')){state.deadlines=state.deadlines.filter(x=>x.id!==b.dataset.remove);await save();deadlines()}})}
function financeSettingsCard(){ensureInsights();const v=state.insights;return card('Indicatori finanziari e navigazione',`<form id="insightsForm"><div class="formgrid"><div><label>Tasso Findomestic lordo (%)</label><input name="rate" type="number" min="0" max="100" step="0.01" value="${Number(v.depositRate)}"></div><div><label>Obiettivo risparmio (%)</label><input name="target" type="number" min="0" max="100" step="1" value="${Number(v.savingTarget)}"></div><div><label>Inflazione NIC annua ISTAT (%)</label><input name="inflation" type="number" min="-20" max="100" step="0.1" placeholder="Da verificare" value="${v.inflation===null?'':esc(v.inflation)}"></div><div><label>Mese del dato (AAAA-MM)</label><input name="inflationMonth" type="month" value="${esc(v.inflationMonth)}"></div><div><label>Stato del dato</label><select name="inflationStatus"><option value="">Da verificare</option><option value="Definitivo" ${v.inflationStatus==='Definitivo'?'selected':''}>Definitivo</option><option value="Provvisorio" ${v.inflationStatus==='Provvisorio'?'selected':''}>Provvisorio</option></select></div><div><label>Link comunicato ufficiale ISTAT</label><input name="source" type="url" placeholder="https://www.istat.it/..." value="${esc(v.inflationSource)}"></div></div><p><label><input type="checkbox" name="navLabels" ${v.navLabels?'checked':''}> Mostra anche il testo sotto le icone di navigazione</label></p><div class="actions"><button class="primary">Salva indicatori</button><button type="button" onclick="checkIstat()">Apri ISTAT</button></div></form><p class="muted">Il valore NIC va trascritto dal comunicato ufficiale. Nessun dato viene presentato come aggiornato automaticamente senza una verifica effettiva.</p>`)}
function initInsightsForm(){const f=$('insightsForm');if(!f)return;f.onsubmit=async e=>{e.preventDefault();const d=new FormData(f);const v=state.insights;v.depositRate=Number(d.get('rate'));v.savingTarget=Number(d.get('target'));v.inflation=d.get('inflation')===''?null:Number(d.get('inflation'));v.inflationMonth=String(d.get('inflationMonth')||'');v.inflationStatus=String(d.get('inflationStatus')||'');v.inflationSource=String(d.get('source')||'');v.navLabels=d.has('navLabels');await save();applyNavLabels();settings()}}
function settings(){ensureCategories();ensureForecast();layout(financeSettingsCard()+catPanel()+card('Budget mensile',`<p class="muted">Modifica le previsioni. Non crea movimenti di denaro.</p><form id="budgetForm"><div class="formgrid"><div><label>Stipendio ordinario</label><input name="income" type="number" min="0" step="0.01" value="${state.incomeMonthly}"></div>${state.budget.map((x,i)=>`<div><label>${esc(x[0])}</label><input name="b${i}" type="number" min="0" step="0.01" value="${x[1]}"></div>`).join('')}${state.allocations.map((x,i)=>`<div><label>Accantonamento: ${esc(x[0])}</label><input name="a${i}" type="number" min="0" step="0.01" value="${x[1]}"></div>`).join('')}</div><div class="actions"><button class="primary">Salva budget</button></div></form>`)+card('Backup e ripristino',`<p>Il database è salvato localmente nel browser. Esporta periodicamente un backup JSON e custodiscilo in un luogo sicuro.</p><div class="actions"><button id="export">Esporta backup JSON</button><button id="csv">Esporta movimenti CSV</button></div><p><label>Importa backup JSON (sostituisce tutti i dati)</label><input type="file" id="import" accept="application/json,.json"></p><div class="notice">Non disinstallare l'app, non cancellare i dati del browser e non usare la modalità in incognito senza avere prima esportato un backup.</div>`)+card('Informazioni',`<p class="muted">Versione 2.4.4 · Dati locali IndexedDB · Nessun account e nessun server. Le scadenze non generano notifiche automatiche e non scalano i saldi: per contabilizzare un pagamento devi registrare la spesa.</p><p class="muted">Le date iniziali dell'assicurazione sono indicative e devono essere corrette. Il budget non costituisce consulenza finanziaria.</p>`));initCats();initInsightsForm();$('budgetForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target);state.incomeMonthly=Number(f.get('income'));state.budget=state.budget.map((x,i)=>[x[0],Number(f.get('b'+i))]);state.allocations=state.allocations.map((x,i)=>[x[0],Number(f.get('a'+i))]);await save();settings()};$('export').onclick=()=>download('family-cfo-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state,null,2),'application/json');$('csv').onclick=()=>{let lines=[['data','tipo','importo','categoria','da','a','descrizione'],...state.transactions.map(t=>[t.date,t.type,t.amount,t.category,t.from,t.to,t.note])];download('family-cfo-movimenti.csv','\ufeff'+lines.map(r=>r.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(';')).join('\r\n'),'text/csv;charset=utf-8')};$('import').onchange=async e=>{let file=e.target.files[0];if(!file)return;try{let obj=JSON.parse(await file.text());if(!valid(obj))throw Error('Formato backup non valido');if(!confirm('Sostituire TUTTI i dati locali con il backup selezionato?'))return;state=obj;await save();dashboard();alert('Backup ripristinato')}catch(err){alert('Importazione non riuscita: '+err.message)}}}
function valid(o){return o&&o.version===1&&Array.isArray(o.accounts)&&o.accounts.length>0&&o.accounts.every(a=>typeof a.id==='string'&&Number.isFinite(a.opening))&&Array.isArray(o.transactions)&&o.transactions.every(t=>typeof t.id==='string'&&typeof t.date==='string'&&Number.isFinite(t.amount)&&['expense','income','transfer'].includes(t.type))&&Array.isArray(o.budget)&&Array.isArray(o.allocations)&&Array.isArray(o.deadlines)&&Number.isFinite(o.incomeMonthly)}function download(name,data,type){let url=URL.createObjectURL(new Blob([data],{type}));let a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}function setTab(x){tab=x;({dashboard,movements,reports,categoriesPage,funds,deadlines,settings,forecast:forecastPage,budgetPage,cashPage}[x])()}window.setTab=setTab;
(async()=>{try{db=await openDB();state=await read();if(!state){state=structuredClone(initial)}ensureGoals();ensureForecast();ensureInsights();ensureV24();await save();applyNavLabels();document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));dashboard();if('serviceWorker'in navigator&&location.protocol==='https:')navigator.serviceWorker.register('./sw.js').catch(()=>{})}catch(e){$('view').innerHTML='<div class="notice">Impossibile avviare il database locale. Apri l’app con Chrome su HTTPS e verifica che lo spazio di archiviazione sia disponibile.</div>';console.error(e)}})();
